package main
import("fmt";"os";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/nanz";"github.com/minz/minzc/pkg/pipeline")
func main(){src,e:=os.ReadFile("/tmp/minz-two-loop-fix/before.nanz");if e!=nil{panic(e)};prefix:=os.Args[1];for _,hg:=range []bool{false,true}{for _,mg:=range []bool{false,true}{name:=fmt.Sprintf("%s-hir%t-mir%t",prefix,hg,mg);m,e:=nanz.Parse(string(src),"two_loops.nanz");if e!=nil{panic(e)};steps,e:=pipeline.CompileHIRSteps(m,pipeline.Options{AssertMode:"none",UseHIRGrace:hg,UseGrace:mg});if e!=nil{panic(e)};os.WriteFile(name+".a80",[]byte(steps.Assembly),0644);os.WriteFile(name+".mir",[]byte(steps.MIR2Raw+"\nOPT:\n"+steps.MIR2Opt),0644);for _,n:=range []int64{0,1,5,255}{for _,mc:=range []int64{0,1,5,255}{lit:=func(x int64)hir.ProfileArgument{return hir.ProfileArgument{Value:&x}};w:=hir.ProfileWorkload{Schema:"minz.profile-workload/v1",TargetModel:"cpm-z80-v1",MaxSteps:1000000,MaxMemory:65536,Calls:[]hir.ProfileInvocation{{Function:"two_loops",Arguments:[]hir.ProfileArgument{lit(65535),lit(2),lit(n),lit(mc)}}}};rawm,e:=nanz.Parse(string(src),"two_loops.nanz");if e!=nil{panic(e)};raw,e:=hir.RunLoopProfile(rawm,w);if e!=nil{panic(e)};want:=int64(uint16((uint32(65535)+2)*uint32(n+mc)));out,e:=pipeline.RunZ80ProfileWorkload(steps,rawm,w,*raw);fmt.Printf("hir=%t mir=%t n=%d m=%d arithmetic=%d raw=%d",hg,mg,n,mc,want,raw.Results[0][0].I);if e!=nil{fmt.Printf(" ERROR %v\n",e)}else{fmt.Printf(" z80=%d\n",out.Invocations[0].Results[0].I)}}}}}}
